local WKTimer = {}

local pausedAt = nil
local timeScale = 1
local timeSpan = 0
local resumeTime = os.time()
local changeTime = os.time()

WKTimer.Paused = false

function pause()
    pausedAt = WKTimer.Timer.GetTimeStamp()
    WKTimer.Paused = true
end

function resume()
    WKTimer.Paused = false
    timeSpan = pausedAt - (getTime() - timeSpan)
end

function getTime()
    if WKTimer.Paused then
        return pausedAt
    end
    local cur =  math.floor(workspace:GetServerTimeNow())
    local passed = (cur - resumeTime) * timeScale
    local t = changeTime + passed

    return t + timeSpan
end

function WKTimer:Toggle()
    if WKTimer.Paused then
        resume()
    else
        pause()
    end
end

function WKTimer:GetDateTime()
    local timestamp = WKTimer.Timer.GetTimeStamp()
    return WKTimer.Timer.GetDateTime(timestamp)
end

function WKTimer:Fade(fadeTime)
    fadeTime = fadeTime or 1
    timeSpan += fadeTime
    if pausedAt then
        pausedAt += fadeTime
    end
end

function WKTimer:SetTimeScale(scale)
    changeTime = getTime()
    resumeTime = os.time()

    timeScale = scale
    timeSpan = 0
end

return function(timer)
    WKTimer.Timer = timer
    local t = WKTimer.Timer.GetTimeStamp()
    WKTimer.Timer.TimeStampProvider = getTime
    return WKTimer
end